/**
 * Blocks sharing of personal contact info in student-facing communication surfaces.
 * Assignments, assessments, and grading stay on-platform.
 */

export const CONTACT_GUARD_MESSAGE =
  "For your safety, sharing personal contacts (phone, email, WhatsApp, Telegram, social handles, etc.) is not allowed. Keep learning conversations on LUC. Assignments and assessments must be submitted through the platform.";

export const CONTACT_GUARD_SHORT =
  "Contact sharing is blocked. Use LUC chat, assignments, and assessments on-platform.";

const CONTACT_PATTERNS = [
  // Emails
  {
    type: 'email',
    regex: /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i,
  },
  // International / local phone numbers (incl. spaced / dashed)
  {
    type: 'phone',
    regex: /(?:\+?\d{1,3}[\s\-.]*)?(?:\(?\d{2,4}\)?[\s\-.]*)?\d{3,4}[\s\-.]?\d{3,4}(?:\s*(?:ext|x|extension)\s*\d+)?/i,
    minDigits: 10,
  },
  // WhatsApp / wa.me / chat.whatsapp
  {
    type: 'whatsapp',
    regex: /(?:whats?\s*app|wa\.me\/|chat\.whatsapp\.com|api\.whatsapp\.com)/i,
  },
  // Telegram
  {
    type: 'telegram',
    regex: /(?:telegram|t\.me\/|tele\.me\/)/i,
  },
  // Signal / Viber / WeChat / Line / Snapchat / Discord invites / Kik
  {
    type: 'messaging_app',
    regex: /(?:\bsignal\b|\bviber\b|\bwechat\b|\bweixin\b|\bline\.me\b|\bsnapchat\b|\bkik\b|discord(?:\.gg|\.com\/invite))/i,
  },
  // Social / contact solicitation phrases
  {
    type: 'social_handle',
    regex: /(?:\b(?:dm|pm)\s+me\b|\bfollow\s+me\b|\badd\s+me\b|\btext\s+me\b|\bcall\s+me\b|\bmessage\s+me\s+on\b|\bhit\s+me\s+up\b|\bmy\s+(?:number|phone|whatsapp|telegram|email|ig|insta|instagram|twitter|x|tiktok|fb|facebook)\b)/i,
  },
  // @handles for common social platforms (avoid matching email which already caught)
  {
    type: 'handle',
    regex: /(?:(?:instagram|insta|ig|twitter|tiktok|facebook|fb|threads)\s*[:@]\s*@?[\w.]{2,}|@[\w.]{3,}\s+on\s+(?:ig|insta|instagram|twitter|tiktok|facebook))/i,
  },
  // Tel / mailto links
  {
    type: 'uri_scheme',
    regex: /(?:tel:|mailto:|sms:)/i,
  },
];

const ALLOWED_ASSIGNMENT_HOSTS = [
  'github.com',
  'gist.github.com',
  'gitlab.com',
  'bitbucket.org',
  'figma.com',
  'www.figma.com',
  'vercel.app',
  'netlify.app',
  'codesandbox.io',
  'stackblitz.com',
  'replit.com',
  'codepen.io',
  'notion.so',
  'www.notion.so',
  'docs.google.com',
  'drive.google.com',
  'sites.google.com',
  'behance.net',
  'www.behance.net',
  'dribbble.com',
  'www.dribbble.com',
  'linkedin.com',
  'www.linkedin.com',
  'youtube.com',
  'www.youtube.com',
  'youtu.be',
  'medium.com',
  'dev.to',
  'hashnode.dev',
  'lucide.app',
];

const BLOCKED_LINK_HOSTS = [
  'wa.me',
  'api.whatsapp.com',
  'chat.whatsapp.com',
  't.me',
  'telegram.me',
  'telegram.org',
  'signal.me',
  'discord.gg',
  'discord.com',
];

function digitCount(text) {
  return (String(text).match(/\d/g) || []).length;
}

/**
 * @param {string} text
 * @returns {{ blocked: boolean, reason?: string, type?: string }}
 */
export function detectContactSharing(text) {
  if (!text || typeof text !== 'string') {
    return { blocked: false };
  }

  const normalized = text.normalize('NFKC');

  for (const pattern of CONTACT_PATTERNS) {
    const match = normalized.match(pattern.regex);
    if (!match) continue;

    if (pattern.minDigits && digitCount(match[0]) < pattern.minDigits) {
      continue;
    }

    // Reduce false positives for short numeric IDs / prices (e.g. "₦15000")
    if (pattern.type === 'phone') {
      const nearby = normalized.slice(
        Math.max(0, match.index - 8),
        Math.min(normalized.length, match.index + match[0].length + 8)
      );
      if (/[₦$€£]|naira|credits?|price|lesson|module|week|percent|%/i.test(nearby) && digitCount(match[0]) < 11) {
        continue;
      }
    }

    return {
      blocked: true,
      type: pattern.type,
      reason: CONTACT_GUARD_MESSAGE,
    };
  }

  return { blocked: false };
}

/**
 * Assert text is free of contact sharing. Throws Error with user-facing message if blocked.
 * @param {string} text
 * @param {string} [customMessage]
 */
export function assertNoContactSharing(text, customMessage = CONTACT_GUARD_MESSAGE) {
  const result = detectContactSharing(text);
  if (result.blocked) {
    const err = new Error(customMessage);
    err.code = 'CONTACT_SHARING_BLOCKED';
    err.type = result.type;
    throw err;
  }
  return true;
}

/**
 * Validate optional project/work links for assignment / proof-of-work submissions.
 * Blocks messaging-app hosts; allows common portfolio / repo hosts.
 * @param {string} url
 * @returns {{ ok: boolean, message?: string }}
 */
export function validatePlatformWorkLink(url) {
  if (!url || !String(url).trim()) {
    return { ok: true };
  }

  const raw = String(url).trim();
  const contact = detectContactSharing(raw);
  if (contact.blocked) {
    return { ok: false, message: CONTACT_GUARD_MESSAGE };
  }

  let hostname = '';
  try {
    const withProtocol = /^https?:\/\//i.test(raw) ? raw : `https://${raw}`;
    hostname = new URL(withProtocol).hostname.toLowerCase().replace(/^www\./, '');
  } catch {
    return { ok: false, message: 'Please enter a valid project URL (e.g. GitHub, Figma, or a live site).' };
  }

  if (BLOCKED_LINK_HOSTS.some((h) => hostname === h || hostname.endsWith(`.${h}`))) {
    return {
      ok: false,
      message: 'Messaging-app links are not allowed. Submit your work through LUC using a portfolio, repo, or document link.',
    };
  }

  const allowed = ALLOWED_ASSIGNMENT_HOSTS.some((h) => {
    const clean = h.replace(/^www\./, '');
    return hostname === clean || hostname.endsWith(`.${clean}`);
  });

  // Allow any non-messaging https host that isn't an obvious contact channel —
  // but prefer known portfolio hosts. Generic personal sites OK if not blocked.
  if (!allowed) {
    // Still OK for student portfolios on custom domains, as long as not contact schemes
    if (/\.(me|link|bio|contact)$/i.test(hostname) || /linktr\.ee|biolink|contact/i.test(hostname)) {
      return {
        ok: false,
        message: 'Personal contact / link-in-bio pages are not allowed. Use a project, repo, or document link instead.',
      };
    }
  }

  return { ok: true };
}
