    async checkDailyAttendance(userId) {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const todayISO = today.toISOString();

        const { data, error } = await supabase
            .from('wallet_transactions')
            .select('id')
            .eq('user_id', userId)
            .eq('transaction_type', 'daily_attendance')
            .gte('created_at', todayISO)
            .limit(1);

        if (error) {
            console.error('Error checking attendance:', error);
            return false;
        }
        return data && data.length > 0;
    },

    async markAttendance(userId) {
        const hasCheckedIn = await this.checkDailyAttendance(userId);
        if (hasCheckedIn) return { success: true, alreadyCheckedIn: true };

        const dateStr = new Date().toISOString().split('T')[0];
        
        // 5 LUC reward for daily attendance
        const data = await this.processWalletTransaction(
            userId, 
            5, 
            'daily_attendance', 
            'Daily Attendance Bonus', 
            dateStr
        );

        return { success: true, alreadyCheckedIn: false, reward: 5 };
    },

