    async placeStoreOrder({ userId, productId, amountCredits, shippingAddress = null }) {
        // 0. Fetch product category to determine fulfillment type
        const { data: product } = await supabase
            .from('store_products')
            .select('category')
            .eq('id', productId)
            .single();

        const initialStatus = product?.category === 'Digital' ? 'delivered' : 'pending';

        // 1. First deduct credits via Edge Function to ensure atomicity
        const { data: transaction, error: txError } = await supabase.functions.invoke('process-transaction', {
            body: {
                p_user_id: userId,
                p_amount: -amountCredits,
                p_type: 'purchase',
                p_description: `Purchase from LUC Store`,
                p_reference_id: productId
            }
        });

        if (txError) throw txError;

        // 2. Create the order record
        const { data: order, error: orderError } = await supabase
            .from('store_orders')
            .insert([{
                user_id: userId,
                product_id: productId,
                amount_credits: amountCredits,
                payment_method: 'credits',
                shipping_address: shippingAddress,
                status: initialStatus
            }])
            .select()
            .single();

        if (orderError) throw orderError;
        return order;
    },


