    // --- Student Tracking (Enrollments & Badges) ---
    async getStudentDetails(userId) {
        // Fetch Enrollments
        const { data: enrollments, error: enrollError } = await supabase
            .from('enrollments')
            .select('*')
            .eq('user_id', userId);

        if (enrollError) throw enrollError;

        // Fetch Granular Lesson Progress (Source of Truth)
        const { data: granular, error: granularError } = await supabase
            .from('lesson_progress')
            .select('*')
            .eq('user_id', userId);

        if (granularError) throw granularError;

        // Fetch User Badges with Badge Details
        const { data: badges, error: badgeError } = await supabase
            .from('user_badges')
            .select(`
                *,
                badge:badges (*)
            `)
            .eq('user_id', userId);

        if (badgeError) throw badgeError;

        return {
            enrollments: enrollments || [],
            granularProgress: granular || [],
            badges: badges?.map(b => ({ ...b.badge, awarded_at: b.awarded_at })) || []
        };
    },

    async enrollUser(userId, type, itemId, amountPaid = 0) {
        const { data, error } = await supabase
            .from('enrollments')
            .upsert([{
                user_id: userId,
                type,
                item_id: itemId,
                amount_paid: amountPaid,
                progress: 0,
                status: 'active'
            }], { 
                onConflict: 'user_id,type,item_id',
                ignoreDuplicates: true 
            })
            .select();

        if (error && error.code !== '23505') throw error; // Ignore unique violation if it still surfaces

        // Auto-join the course chat channel
        if (type === 'academy' || type === 'vault') {
            try {
                await this.joinCourseChat(userId, itemId);
            } catch (chatErr) {
                console.warn("Failed to join course chat during enrollment:", chatErr);
            }
        }

        return data ? data[0] : null;
    },

    async unenrollUser(userId, type, itemId) {
        // 1. Delete enrollment record
        const { error: enrollError } = await supabase
            .from('enrollments')
            .delete()
            .eq('user_id', userId)
            .eq('type', type)
            .eq('item_id', itemId);

        if (enrollError) throw enrollError;

        // 2. Delete granular progress for this course
        await supabase
            .from('lesson_progress')
            .delete()
            .eq('user_id', userId)
            .eq('course_id', itemId);

        // 3. Leave course chat
        try {
            await this.leaveCourseChat(userId, itemId);
        } catch (chatErr) {
            console.warn("Failed to leave course chat during unenrollment:", chatErr);
        }

        return true;
    },

