    async getPaymentRequestStats() {
        const { data, error } = await supabase
            .from('payment_requests')
            .select('status, amount');

        if (error) throw error;

        const stats = {
            total: data.length,
            pending: 0,
            confirmed: 0,
            rejected: 0,
            unenrolled: 0,
            totalRevenue: 0,
            pendingAmount: 0,
        };

        for (const row of data) {
            if (row.status === 'pending') {
                stats.pending += 1;
                stats.pendingAmount += row.amount || 0;
            } else if (row.status === 'confirmed') {
                stats.confirmed += 1;
                stats.totalRevenue += row.amount || 0;
            } else if (row.status === 'rejected') {
                stats.rejected += 1;
            } else if (row.status === 'unenrolled') {
                stats.unenrolled += 1;
            }
        }

        return stats;
    },

    async updateStudentProgress(userId, itemId, progress, status = 'active', type = 'academy') {
        const itemIdStr = String(itemId).trim();
        const safeProgress = isNaN(progress) || progress === null ? 0 : Number(progress);
        const safeType = type || 'academy'; // Prevent null type constraint violation

        const updates = {
            progress: safeProgress,
            status,
            updated_at: new Date()
        };
        if (status === 'completed') updates.completed_at = new Date();

        // 1. Try updating with strict type matching first (Safest)
        let query = supabase
            .from('enrollments')
            .update(updates)
            .eq('user_id', userId)
            .eq('item_id', itemIdStr)
            .eq('type', safeType);

        const { data, error } = await query.select();

        if (error) {
            console.error("Supabase UpdateEnrollment Error Details:", error);
            throw error;
        }

        // 2. Comprehensive Fallback Strategy
        let finalResult = data?.[0];

        if (!finalResult) {
            console.warn(`Strict update failed for ${itemIdStr}. Entering self-healing mode...`);

            // 2a. Check if ANY enrollment exists for this item (regardless of type)
            const { data: existing, error: checkError } = await supabase
                .from('enrollments')
                .select('*')
                .eq('user_id', userId)
                .eq('item_id', itemIdStr);

            if (checkError) throw checkError;

            if (existing && existing.length > 0) {
                // Record exists but maybe with a different type or we just missed it
                const recordId = existing[0].id;
                console.info(`Found existing enrollment ${recordId} for ${itemIdStr}. Updating by record ID.`);

                const { data: retryData, error: retryError } = await supabase
                    .from('enrollments')
                    .update(updates)
                    .eq('id', recordId)
                    .select();

                if (retryError) throw retryError;
                finalResult = retryData?.[0];
            } else if (type) {
                // 3. Self-healing: Record doesn't exist at all. Create it!
                console.warn(`No enrollment record found for ${itemIdStr}. Creating new ${type} enrollment.`);

                const newRecord = {
                    user_id: userId,
                    type: type, // 'academy' or 'vault'
                    item_id: itemIdStr,
                    progress: progress || 0,
                    status: status || 'active',
                    amount_paid: 0,
                    completed_at: status === 'completed' ? new Date() : null,
                    updated_at: new Date()
                };

                const { data: insertData, error: insertError } = await supabase
                    .from('enrollments')
                    .insert([newRecord])
                    .select();

                if (insertError) {
                    // Handle race condition: if it was created in the last millisecond
                    if (insertError.message?.includes('unique constraint')) {
                        const { data: finalFetch } = await supabase
                            .from('enrollments')
                            .select('*')
                            .eq('user_id', userId)
                            .eq('item_id', itemIdStr);
                        finalResult = finalFetch?.[0];
                    } else {
                        console.error("Auto-enrollment failed:", insertError);
                        throw insertError;
                    }
                } else {
                    finalResult = insertData?.[0];
                }
            }
        }

        return finalResult;
    },

