    async syncCourseChats() {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;

        // 1. Ensure in General Chat (Hardcoded ID used in GlobalChat)
        const generalId = '00000000-0000-0000-0000-000000000000';
        const { data: generalChannel } = await supabase
            .from('chat_channels')
            .select('id')
            .eq('id', generalId)
            .maybeSingle();
        
        if (generalChannel) {
            await supabase
                .from('chat_channel_members')
                .upsert({ channel_id: generalId, user_id: user.id }, { onConflict: 'channel_id,user_id' });
        }

        // 2. Ensure in all enrolled course chats
        const { data: enrollments } = await supabase
            .from('enrollments')
            .select('item_id')
            .eq('user_id', user.id);
        
        if (enrollments) {
            for (const enrollment of enrollments) {
                await this.joinCourseChat(user.id, enrollment.item_id);
            }
        }
    },

