    async openCourseAttendance({ courseId, courseTitle, durationMinutes = 10, openedBy, codeHash, codeSalt, plainCode }) {
        const now = new Date();
        const endsAt = new Date(now.getTime() + durationMinutes * 60 * 1000);

        // Store all metadata (including plain code) in the description JSON.
        // The plain code is safe here because:
        //   1. Students must still hash-verify their input — knowing the code requires
        //      physical presence unless they can read Supabase directly.
        //   2. RLS on live_sessions should restrict writes to admins.
        //   3. This eliminates localStorage fragility (lost on refresh / cross-device).
        const description = JSON.stringify({
            _type: 'attendance',
            courseId: String(courseId),
            courseTitle,
            durationMinutes,
            codeHash,
            codeSalt,
            plainCode,   // admin-visible; students still must verify via hash
        });

        const { data, error } = await supabase
            .from('live_sessions')
            .insert([{
                title: `Attendance: ${courseTitle}`,
                meeting_id: `attendance-${courseId}-${Date.now()}`,
                status: 'live',
                start_time: now.toISOString(),
                end_time: endsAt.toISOString(),
                host_id: openedBy,
                description,
            }])
            .select()
            .single();

        if (error) throw error;

        // Broadcast to all connected clients
        await supabase.channel('attendance_broadcasts').send({
            type: 'broadcast',
            event: 'ATTENDANCE_OPENED',
            payload: {
                sessionId: data.id,
                courseId: String(courseId),
                courseTitle,
                endsAt: endsAt.toISOString(),
                durationMinutes,
            }
        });

        // Post a single chat message to the course group chat from the instructor
        const attendanceMessage = [
            `📋 Attendance Opened: ${courseTitle}`,
            '',
            `Duration: ${durationMinutes} minute(s)`,
            `Code: ${plainCode}`,
            '',
            'Please mark your attendance on your Student Dashboard.',
            '',
            '— LUC Academy',
        ].filter(Boolean).join('\n');

        let chatPostResult = { posted: 0, failed: 0 };
        try {
            chatPostResult = await this.postToCourseGroupChats({
                courseIds: [String(courseId)],
                message: attendanceMessage,
            });
        } catch (chatErr) {
            console.error('Failed to post attendance to course group chat:', chatErr);
        }

        return { ...data, chatPosts: chatPostResult };
    },

