    async submitCourseWork({ userId, trackId, courseId, sessionId, workType, submissionText, fileUrl = null, trackCourseIds = [], scope = 'track' }) {
        assertNoContactSharing(submissionText || '');
        if (fileUrl) {
            assertNoContactSharing(fileUrl);
            const linkCheck = validatePlatformWorkLink(fileUrl);
            if (!linkCheck.ok) {
                const err = new Error(linkCheck.message);
                err.code = 'INVALID_WORK_LINK';
                throw err;
            }
        }

        // Captains delegating submissions for teammates skip the enrollee check
        const { data: { session: _authSess } } = await supabase.auth.getSession();
        const _isDelegating = _authSess?.user?.id && userId !== _authSess.user.id;
        if (!_isDelegating) {
            if (scope === 'track' && trackCourseIds.length) {
                const enrolled = await this.isUserEnrolledInTrack(userId, trackCourseIds);
                if (!enrolled) {
                    throw new Error('You must be enrolled in this learning track to submit.');
                }
            } else if (scope === 'course' && courseId) {
                const enrolled = await this.isUserEnrolledInCourse(userId, courseId);
                if (!enrolled) {
                    throw new Error('You must be enrolled in this course to submit.');
                }
            }
        }

        const lessonId = this._workLessonId(sessionId, workType);
        const submittedAt = new Date().toISOString();
        const storageId = scope === 'course' ? String(courseId) : String(trackId);

        const { data, error } = await supabase
            .from('lesson_progress')
            .upsert({
                user_id: userId,
                course_id: storageId,
                lesson_id: lessonId,
                completed: true,
                last_timestamp: 0,
                last_accessed_at: submittedAt,
                assessment_data: {
                    type: workType,
                    scope,
                    ...(scope === 'track' ? { trackId: storageId } : { courseId: storageId }),
                    sessionId,
                    submissionText,
                    fileUrl,
                    submittedAt,
                },
            }, { onConflict: 'user_id,course_id,lesson_id' })
            .select()
            .single();

        if (error) throw error;

        if (workType === 'assignment') {
            const session = await supabase
                .from('live_sessions')
                .select('description, host_id')
                .eq('id', sessionId)
                .single();

            let meta = {};
            try { meta = JSON.parse(session.data?.description || '{}'); } catch (_) {}

            const scopeLabel = scope === 'course' ? `Course: ${meta.courseTitle || 'Course'}` : `Track: ${meta.trackTitle || 'Track'}`;

            await this.submitAssignment({
                student_id: userId,
                course_id: storageId,
                instructor_id: session.data?.host_id,
                submission_text: `[${scopeLabel} · ${meta.workTitle || 'Assignment'}]\n\n${submissionText}`,
                file_url: fileUrl || null,
                status: 'pending',
            });
        }

        return data;
    },

    async hasSubmittedCourseWork({ userId, sessionId, workType }) {
        const lessonId = this._workLessonId(sessionId, workType);
        const { data, error } = await supabase
            .from('lesson_progress')
            .select('id')
            .eq('user_id', userId)
            .eq('lesson_id', lessonId)
            .limit(1);

        if (error) return false;
        return data && data.length > 0;
    },

    async getCourseWorkRoster({ trackId, trackCourseIds, courseId, sessionId, workType, scope = 'track' }) {
        const lessonId = this._workLessonId(sessionId, workType);
        const storageId = scope === 'course' ? String(courseId) : String(trackId);

        let enrolled;
        if (scope === 'course' && courseId) {
            enrolled = await this.getCourseEnrolledStudents(courseId);
        } else {
            enrolled = await this.getTrackEnrolledStudents(trackCourseIds);
        }

        const { data: submissions, error: subError } = await supabase
            .from('lesson_progress')
            .select('user_id, assessment_data, last_accessed_at')
            .eq('course_id', storageId)
            .eq('lesson_id', lessonId)
            .eq('completed', true);

        if (subError) throw subError;

        const submissionMap = new Map((submissions || []).map(s => [s.user_id, s]));

        return enrolled.map(e => {
            const sub = submissionMap.get(e.user_id);
            const assessmentData = sub?.assessment_data || {};
            return {
                userId: e.user_id,
                fullName: e.profile?.full_name || 'Unknown',
                email: e.profile?.email || '',
                avatarUrl: e.profile?.avatar_url,
                hasSubmitted: !!sub,
                submittedAt: sub?.last_accessed_at || assessmentData.submittedAt,
                submissionPreview: assessmentData.submissionText
                    ? String(assessmentData.submissionText).slice(0, 120)
                    : null,
                submissionText: assessmentData.submissionText ? String(assessmentData.submissionText) : null,
                fileUrl: assessmentData.fileUrl || null,
            };
        });
    },

