    async validateInstructorPromoCode(code, courseId, trackCourseIds) {
        if (!code) return null;

        const { data: promoCode, error } = await supabase
            .from('instructor_promo_codes')
            .select('id, instructor_id, code, discount_percent, is_active')
            .ilike('code', code.trim())
            .eq('is_active', true)
            .maybeSingle();

        if (error || !promoCode) return null;

        const { data: courses } = await supabase
            .from('site_content')
            .select('data')
            .eq('id', 'academy')
            .single();

        const allCourses = courses?.data || [];

        if (trackCourseIds && trackCourseIds.length > 0) {
            const hasMatchingCourse = trackCourseIds.some(tId => {
                const course = allCourses.find(c => String(c.id) === String(tId));
                if (!course) return false;
                const instructorIds = Array.isArray(course.instructor_id)
                    ? course.instructor_id
                    : course.instructor_id ? [course.instructor_id] : [];
                return instructorIds.includes(promoCode.instructor_id);
            });
            if (!hasMatchingCourse) return null;
        } else if (courseId) {
            const course = allCourses.find(c => String(c.id) === String(courseId));
            if (!course) return null;
            const instructorIds = Array.isArray(course.instructor_id)
                ? course.instructor_id
                : course.instructor_id ? [course.instructor_id] : [];
            if (!instructorIds.includes(promoCode.instructor_id)) return null;
        } else {
            return null;
        }

        return promoCode;
    },

