    // Shared helper for platform-wide broadcasts
    async broadcastGlobalNotification(event, payload) {
        try {
            console.log(`Attempting to broadcast ${event}...`, payload);
            const channelName = 'platform_notifications';
            const channel = supabase.channel(channelName);
            
            const sendBroadcast = async () => {
                await channel.send({
                    type: 'broadcast',
                    event: event,
                    payload: payload
                });
                console.log(`Successfully broadcasted ${event}`);
            };

            // Check if already connected/joined
            if (channel.state === 'joined') {
                await sendBroadcast();
            } else {
                channel.subscribe(async (status) => {
                    if (status === 'SUBSCRIBED') {
                        await sendBroadcast();
                        // If we created this subscription just for sending, we could clean it up,
                        // but since platform_notifications is used globally, we leave it.
                    } else if (status === 'CHANNEL_ERROR') {
                        console.error(`Channel error while trying to broadcast ${event}`);
                    }
                });
            }
        } catch (err) {
            console.error(`Failed to broadcast ${event}:`, err);
        }
    },

    // Helper for Admin-only broadcasts
    async broadcastAdminNotification(event, payload) {
        try {
            console.log(`Attempting to broadcast ${event} to admins...`, payload);
            const channelName = 'admin_notifications';
            const channel = supabase.channel(channelName);
            
            const sendBroadcast = async () => {
                await channel.send({
                    type: 'broadcast',
                    event: event,
                    payload: payload
                });
                console.log(`Successfully broadcasted ${event} to admins`);
            };

            // Check if already connected/joined
            if (channel.state === 'joined') {
                await sendBroadcast();
            } else {
                channel.subscribe(async (status) => {
                    if (status === 'SUBSCRIBED') {
                        await sendBroadcast();
                    } else if (status === 'CHANNEL_ERROR') {
                        console.error(`Channel error while trying to broadcast ${event} to admins`);
                    }
                });
            }
        } catch (err) {
            console.error(`Failed to broadcast ${event} to admins:`, err);
        }
    },

