    async issueCertificate(studentId, courseId, instructorId, trackCourseIds = null) {
        // First check if already exists
        const { data: existing } = await supabase
            .from('course_certificates')
            .select('*')
            .eq('student_id', studentId)
            .eq('course_id', courseId)
            .single();

        if (existing) return existing;

        // If this course is part of a track, enforce 70% attendance
        if (trackCourseIds?.length) {
            const stats = await this.getTrackAttendanceStats(studentId, trackCourseIds);
            if (stats.percentage < 70) {
                const err = new Error(
                    `Attendance requirement not met. You need at least 70% attendance to graduate from this track. Your current attendance is ${stats.percentage}% (${stats.attended}/${stats.total} sessions).`
                );
                err.code = 'ATTENDANCE_REQUIREMENT';
                err.attendanceStats = stats;
                throw err;
            }
        }

        // Generate a UID
        const certUid = `LUC-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 10).toUpperCase()}`;

        const { data, error } = await supabase
            .from('course_certificates')
            .insert([{
                certificate_uid: certUid,
                student_id: studentId,
                course_id: courseId,
                instructor_id: instructorId,
                issue_date: new Date().toISOString()
            }])
            .select()
            .single();

        if (error) throw error;
        return data;
    },

