    // ── Track Attendance (for graduation gating) ──────────────────────

    async getTrackAttendanceStats(userId, trackCourseIds) {
        if (!trackCourseIds?.length) return { total: 0, attended: 0, percentage: 0 };

        const courseIds = trackCourseIds.map(String);

        const { data: sessions, error: sessError } = await supabase
            .from('live_sessions')
            .select('id, description')
            .in('status', ['completed', 'live']);

        if (sessError) throw sessError;

        const relevantSessions = (sessions || []).filter(s => {
            try {
                const meta = JSON.parse(s.description || '{}');
                return meta._type === 'attendance' && courseIds.includes(String(meta.courseId));
            } catch { return false; }
        });

        const total = relevantSessions.length;

        const { data: marked, error: markError } = await supabase
            .from('lesson_progress')
            .select('lesson_id')
            .eq('user_id', userId)
            .like('lesson_id', 'ATTENDANCE_%')
            .eq('completed', true);

        if (markError) throw markError;

        const markedLessonIds = (marked || []).map(m => m.lesson_id);
        const attended = relevantSessions.filter(s =>
            markedLessonIds.some(id => id.endsWith(`_${s.id}`))
        ).length;

        const percentage = total > 0 ? Math.round((attended / total) * 100) : 0;
        return { total, attended, percentage };
    },


    async getTrackStudents(trackCourseIds) {
        if (!trackCourseIds?.length) return [];
        const { data, error } = await supabase
            .from('camp_registrations')
            .select('user_id, studentsdata, created_at')
            .in('course_id', trackCourseIds.map(String));
        if (error) {
            console.error('Error fetching track students:', error);
            return [];
        }
        // Flatten: each registration may have multiple students in studentsData
        const result = [];
        for (const reg of data || []) {
            const students = Array.isArray(reg.studentsdata) && reg.studentsdata.length > 0
                ? reg.studentsdata
                : [];
            if (students.length > 0) {
                students.forEach(s => result.push({
                    user_id: reg.user_id,
                    studentFullName: s.studentFullName || s.full_name || '',
                    studentAge: s.studentAge || s.age || '',
                    created_at: reg.created_at
                }));
            } else {
                // Fallback: no studentsData, skip (can't read top-level camelCase columns)
            }
        }
        return result;
    },

    async getTrackCaptains(trackCourseIds) {
        if (!trackCourseIds?.length) return null;
        
        const { data, error } = await supabase
            .from('camp_registrations')
            .select('user_id, studentsdata, created_at')
            .in('course_id', trackCourseIds.map(String));

        if (error) {
            console.error('Error fetching track captains:', error);
            return null;
        }
        
        if (!data || data.length === 0) return null;

        // Flatten studentsData JSONB into individual student records
        const flattened = [];
        for (const reg of data) {
            const students = Array.isArray(reg.studentsdata) && reg.studentsdata.length > 0
                ? reg.studentsdata
                : [];
            students.forEach(s => flattened.push({
                user_id: reg.user_id,
                studentFullName: s.studentFullName || s.full_name || '',
                studentAge: s.studentAge || s.age || '',
                created_at: reg.created_at
            }));
        }

        // Parse ages, filter out invalid ones
        const validStudents = flattened.map(s => ({
            ...s,
            ageNum: parseInt(String(s.studentAge).replace(/[^0-9]/g, ''), 10)
        })).filter(s => !isNaN(s.ageNum));

        if (validStudents.length === 0) return null;

        // Sort: Oldest first (highest ageNum). Tiebreaker: earliest created_at first.
        validStudents.sort((a, b) => {
            if (b.ageNum !== a.ageNum) return b.ageNum - a.ageNum;
            return new Date(a.created_at) - new Date(b.created_at);
        });

        const captain = validStudents[0];

        const youngestStudents = [...validStudents].sort((a, b) => {
            if (a.ageNum !== b.ageNum) return a.ageNum - b.ageNum;
            return new Date(a.created_at) - new Date(b.created_at);
        });

        const assistantCaptain = youngestStudents[0];

        if (captain.user_id === assistantCaptain.user_id) {
            return { captain, assistantCaptain: null };
        }

        return { captain, assistantCaptain };
    },

    async assignTrackCaptains(trackCourseIds) {
        if (!trackCourseIds?.length) return null;
        
        const captains = await this.getTrackCaptains(trackCourseIds);
        if (!captains) return null;
        
        return {
            captain: captains.captain ? {
                user_id: captains.captain.user_id,
                studentFullName: captains.captain.studentFullName,
                ageNum: captains.captain.ageNum
            } : null,
            assistantCaptain: captains.assistantCaptain ? {
                user_id: captains.assistantCaptain.user_id,
                studentFullName: captains.assistantCaptain.studentFullName,
                ageNum: captains.assistantCaptain.ageNum
            } : null,
            assignedAt: new Date().toISOString()
        };
    },

    async getTrackAttendanceStatsForAllStudents(trackCourseIds) {
        if (!trackCourseIds?.length) return [];

        const courseIds = trackCourseIds.map(String);

        const { data: sessions, error: sessError } = await supabase
            .from('live_sessions')
            .select('id, description')
            .in('status', ['completed', 'live']);

        if (sessError) throw sessError;

        const relevantSessions = (sessions || []).filter(s => {
            try {
                const meta = JSON.parse(s.description || '{}');
                return meta._type === 'attendance' && courseIds.includes(String(meta.courseId));
            } catch { return false; }
        });

        const total = relevantSessions.length;
        const sessionIds = new Set(relevantSessions.map(s => s.id));

        const { data: allMarked, error: markError } = await supabase
            .from('lesson_progress')
            .select('user_id, lesson_id')
            .like('lesson_id', 'ATTENDANCE_%')
            .eq('completed', true);

        if (markError) throw markError;

        const studentCount = new Map();
        (allMarked || []).forEach(rec => {
            const matched = [...sessionIds].some(id => rec.lesson_id.endsWith(`_${id}`));
            if (matched) {
                studentCount.set(rec.user_id, (studentCount.get(rec.user_id) || 0) + 1);
            }
        });

        const userIds = [...studentCount.keys()];
        let profiles = [];
        if (userIds.length > 0) {
            const { data: prof } = await supabase
                .from('profiles')
                .select('id, full_name, email, avatar_url')
                .in('id', userIds);
            if (prof) profiles = prof;
        }

        const profileMap = new Map(profiles.map(p => [p.id, p]));

        return userIds.map(id => {
            const attended = studentCount.get(id) || 0;
            const percentage = total > 0 ? Math.round((attended / total) * 100) : 0;
            const p = profileMap.get(id) || {};
            return {
                userId: id,
                fullName: p.full_name || 'Unknown',
                email: p.email || '',
                avatarUrl: p.avatar_url,
                attended,
                total,
                percentage,
                meetsRequirement: percentage >= 70,
            };
        }).sort((a, b) => b.percentage - a.percentage);
    },

