    async getUserActivityTimeline(userId) {
        try {
            // Using allSettled to ensure that even if one table is missing or restricted, we get the rest.
            const results = await Promise.allSettled([
                // Learning Activity
                supabase.from('lesson_progress').select('created_at').eq('user_id', userId),
                supabase.from('enrollments').select('created_at').eq('user_id', userId),
                // Engagement Activity
                supabase.from('squad_applications').select('created_at').eq('user_id', userId),
                // Achievement Activity (POW uses student_id based on other service methods)
                supabase.from('proof_of_work_submissions').select('created_at').eq('student_id', userId),
                // Community Contributions (opportunity_submissions uses submitter_email, not user_id — skip for activity timeline)
            ]);

            // Filter successful results and combine data
            const allData = results
                .filter(r => r.status === 'fulfilled' && !r.value.error)
                .map(r => r.value.data)
                .flat();

            if (allData.length === 0) {
                // Check if there was a global error in the first successful-looking result
                const errors = results.filter(r => r.status === 'fulfilled' && r.value.error);
                if (errors.length > 0) {
                    console.warn("Some activity sources failed:", errors.map(e => e.value.error.message));
                }
            }

            // Normalize all timestamps to YYYY-MM-DD
            const activityDates = allData
                .filter(a => a && a.created_at)
                .map(a => new Date(a.created_at).toISOString().split('T')[0]);

            // Return counts per day
            const counts = activityDates.reduce((acc, date) => {
                acc[date] = (acc[date] || 0) + 1;
                return acc;
            }, {});

            return counts;
        } catch (error) {
            console.error("Failed to fetch activity timeline:", error);
            return {};
        }
    },

