    async pickScholarForCourse(courseId, type = 'academy') {
        try {
            // 1. Get all students NOT enrolled in this course
            const { data: users, error: userError } = await supabase
                .from('profiles')
                .select('id, full_name, avatar_url, last_seen_at, status_mode')
                .eq('suspended', false);

            if (userError) throw userError;

            const { data: enrollments, error: enrollError } = await supabase
                .from('enrollments')
                .select('user_id')
                .eq('item_id', String(courseId))
                .eq('type', type);
            
            if (enrollError) throw enrollError;

            const enrolledIds = new Set((enrollments || []).map(e => e.user_id));
            const potentialScholars = (users || []).filter(u => !enrolledIds.has(u.id));

            if (potentialScholars.length === 0) throw new Error("No eligible scholars found.");

            // 2. Merit-Based Scoring (The 'LUC Brain' Logic)
            const scoredScholars = potentialScholars.map(u => {
                let score = Math.random() * 40; // Base luck
                const lastSeen = u.last_seen_at ? new Date(u.last_seen_at) : null;
                const now = new Date();
                
                // Favor active users (within last 7 days)
                if (lastSeen && (now - lastSeen) / (1000 * 60 * 60 * 24) < 7) {
                    score += 50; 
                }
                
                // Favor users with established profiles
                if (u.avatar_url) score += 10;
                
                return { ...u, score };
            });

            // Sort by score and pick the best one
            scoredScholars.sort((a, b) => b.score - a.score);
            const winner = scoredScholars[0];

            // 3. Enroll the winner with amount_paid = 0 to mark it as a scholarship
            await this.enrollUser(winner.id, type, String(courseId), 0);

            return winner;
        } catch (error) {
            console.error("Scholarship selection failed:", error);
            throw error;
        }
    },

